package run.ikaros.document;
import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; import run.ikaros.resource.CreateResourceRequest; import run.ikaros.resource.ResourceService; import run.ikaros.resource.ResourceType;
@Service public class PersistentDocumentService implements DocumentService{private final ResourceService resources;private final DocumentRepository documents;private final DocumentWorkingCopyRepository copies;private final DocumentRevisionRepository revisions;private final DocumentPublicationRepository publications;public PersistentDocumentService(ResourceService r,DocumentRepository d,DocumentWorkingCopyRepository c,DocumentRevisionRepository v,DocumentPublicationRepository p){resources=r;documents=d;copies=c;revisions=v;publications=p;}
 @Override public Mono<DocumentView> create(UUID o,CreateDocumentRequest r){String locale=r.locale()==null||r.locale().isBlank()?"en-US":r.locale();ResourceType type=r.kind()==DocumentKind.ARTICLE?ResourceType.ARTICLE:ResourceType.DOCUMENT;return resources.create(o,new CreateResourceRequest(type,r.title(),locale)).flatMap(x->{Instant now=Instant.now();return documents.save(new DocumentEntity(null,o,x.id(),r.kind(),null,now,now,null)).flatMap(d->copies.save(new DocumentWorkingCopyEntity(null,d.id(),o,r.content()==null?"":r.content(),"v1",null,now,null)).thenReturn(d));}).map(this::view);}
 @Override public Flux<DocumentView> list(UUID o){return documents.findAllByOwnerIdOrderByUpdatedAtDesc(o).map(this::view);}@Override public Mono<WorkingCopyView> workingCopy(UUID o,UUID id){return owned(o,id).then(copies.findByDocumentId(id).switchIfEmpty(Mono.error(new NotFoundException("Working Copy 不存在"))).map(this::copyView));}
 @Override public Mono<WorkingCopyView> updateWorkingCopy(UUID o,UUID id,UpdateWorkingCopyRequest r){return owned(o,id).then(copies.findByDocumentId(id).switchIfEmpty(Mono.error(new NotFoundException("Working Copy 不存在")))).flatMap(c->{if(version(c.version())!=r.expectedVersion())return Mono.error(new ConflictException("Working Copy 版本冲突"));return copies.save(new DocumentWorkingCopyEntity(c.id(),c.documentId(),c.ownerId(),r.content(),r.contentSchemaVersion(),c.baseRevisionId(),Instant.now(),c.version()));}).map(this::copyView);}
 @Override public Mono<RevisionView> commit(UUID o,UUID id,CommitRevisionRequest r){return owned(o,id).then(copies.findByDocumentId(id).switchIfEmpty(Mono.error(new NotFoundException("Working Copy 不存在")))).flatMap(c->{if(version(c.version())!=r.expectedVersion())return Mono.error(new ConflictException("Working Copy 版本冲突"));return revisions.findTopByDocumentIdOrderByRevisionNumberDesc(id).map(x->x.revisionNumber()+1).defaultIfEmpty(1L).flatMap(n->revisions.save(new DocumentRevisionEntity(null,id,o,n,r.content(),r.contentSchemaVersion(),Instant.now(),o)).flatMap(v->documents.findById(id).flatMap(d->documents.save(new DocumentEntity(d.id(),d.ownerId(),d.resourceId(),d.kind(),v.id(),d.createdAt(),Instant.now(),d.version()))).then(copies.save(new DocumentWorkingCopyEntity(c.id(),c.documentId(),c.ownerId(),r.content(),r.contentSchemaVersion(),v.id(),Instant.now(),c.version())).thenReturn(v))));}).map(this::revisionView);}
 @Override public Flux<RevisionView> revisions(UUID o,UUID id){return owned(o,id).thenMany(revisions.findAllByDocumentIdOrderByRevisionNumberDesc(id).map(this::revisionView));}@Override public Mono<RevisionView> restore(UUID o,UUID id,long n){return owned(o,id).then(revisions.findAllByDocumentIdOrderByRevisionNumberDesc(id).filter(v->v.revisionNumber()==n).next().switchIfEmpty(Mono.error(new NotFoundException("Revision 不存在"))).flatMap(old->revisions.findTopByDocumentIdOrderByRevisionNumberDesc(id).flatMap(last->revisions.save(new DocumentRevisionEntity(null,id,o,last.revisionNumber()+1,old.content(),old.contentSchemaVersion(),Instant.now(),o)))).map(this::revisionView));}
 @Override public Mono<DocumentPublicationEntity> publish(UUID o,UUID id,PublishDocumentRequest r){return owned(o,id).then(revisions.findAllByDocumentIdOrderByRevisionNumberDesc(id).filter(v->v.revisionNumber()==r.revisionNumber()).next().switchIfEmpty(Mono.error(new NotFoundException("Revision 不存在")))).flatMap(v->publications.findByDocumentId(id).flatMap(p->publications.save(new DocumentPublicationEntity(p.id(),id,v.id(),r.slug(),DocumentPublicationState.PUBLISHED,Instant.now(),p.version()))).switchIfEmpty(publications.save(new DocumentPublicationEntity(null,id,v.id(),r.slug(),DocumentPublicationState.PUBLISHED,Instant.now(),null))));}@Override public Mono<DocumentPublicationEntity> unpublish(UUID o,UUID id){return owned(o,id).then(publications.findByDocumentId(id).switchIfEmpty(Mono.error(new NotFoundException("Publication 不存在"))).flatMap(p->publications.save(new DocumentPublicationEntity(p.id(),p.documentId(),p.revisionId(),p.slug(),DocumentPublicationState.UNPUBLISHED,p.publishedAt(),p.version()))));}
 private Mono<DocumentEntity> owned(UUID o,UUID id){return documents.findById(id).filter(d->d.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Document 不存在或无权访问")));}private long version(Long v){return v==null?0:v;}private DocumentView view(DocumentEntity d){return new DocumentView(d.id(),d.resourceId(),d.kind(),d.currentRevisionId());}private WorkingCopyView copyView(DocumentWorkingCopyEntity c){return new WorkingCopyView(c.documentId(),c.content(),c.contentSchemaVersion(),c.baseRevisionId(),c.updatedAt(),version(c.version()));}private RevisionView revisionView(DocumentRevisionEntity r){return new RevisionView(r.id(),r.documentId(),r.revisionNumber(),r.content(),r.contentSchemaVersion(),r.createdAt());}}
